from bank_core import *
def questions(v=0):
 b=Bank(7,v);a=3+v;k=2+v;t='تعریف و ساده‌کردن عبارت گویا';o='محاسبات عبارت‌های گویا';d='تقسیم چندجمله‌ای‌ها'
 b.m(1,'تشخیص عبارت گویا',t,'کدام عبارت، نسبت دو چندجمله‌ای است؟','(x²+1)/(x−2)',['√x/(x+1)','|x|/(x+1)','2^x/(x+1)'],'در عبارت گویا، صورت و مخرج باید چندجمله‌ای باشند و مخرج چندجمله‌ای صفر نباشد.')
 b.n(1,'صفر مخرج خطی',t,f'عبارت 1/(x−{a}) به ازای چه x تعریف نشده است؟',a,'مقدار ممنوع از صفر کردن مخرج به دست می‌آید، نه صورت.',f'{a}')
 b.s(1,'صفرهای مخرج حاصل‌ضربی',t,f'مقدارهای تعریف‌نشدهٔ 1/[x(x−{a})] را به صورت مجموعه بنویس.',[0,a],'هر عامل مخرج را جدا برابر صفر قرار بده.')
 b.n(1,'مقدار عددی یک عبارت گویا',t,f'مقدار (x+{a})/(x−1) برای x={a+2} چند است؟',F(2*a+2,a+1),'اول مجاز بودن مقدار را در مخرج کنترل و سپس جایگذاری کن.',f'({a+2}+{a})/({a+2}-1)')
 b.n(1,'حذف عامل مشترک عددی در کسر جبری',t,f'برای x≠0، مقدار ({k*a}x)/({k}x) چند است؟',a,'عامل مشترک ناصفر از صورت و مخرج حذف می‌شود.',f'cancel(({k*a}*x)/({k}*x))')
 b.m(1,'حفظ محدودیت پس از حذف عامل',t,f'عبارت (x−{a})/(x−{a}) در چه دامنه‌ای برابر یک است؟',f'x≠{a}',[f'همهٔ عددهای حقیقی',f'فقط x={a}','هیچ عددی'],'حذف عامل، ممنوعیتِ مخرج اولیه را از بین نمی‌برد.')
 b.n(1,'جمع کسرهای هم‌مخرج با صورت ثابت',o,f'در حاصل {a}/x+{k}/x=(c)/x با x≠0، c چند است؟',a+k,'در مخرج‌های برابر فقط صورت‌ها جمع می‌شوند.',f'{a}+{k}')
 b.n(1,'تفریق کسرهای هم‌مخرج',o,f'در حاصل ({a}x+{k})/(x+1)−({a}x−1)/(x+1)=c/(x+1)، c چند است؟',k+1,'علامت منفی را به تمام صورت دوم اعمال کن.',f'expand(({a}*x+{k})-({a}*x-1))')
 b.n(1,'ضرب دو کسر سادهٔ جبری',o,f'برای x≠0، حاصل ({a}/x)×(x/{k}) چند است؟',F(a,k),'صورت‌ها و مخرج‌ها ضرب می‌شوند و عامل مشترک x حذف می‌شود.',f'cancel(({a}/x)*(x/{k}))')
 b.n(1,'تقسیم بر کسر و وارون کردن مقسوم‌علیه',o,f'برای x≠0، حاصل ({a}/x)÷({k}/x) چند است؟',F(a,k),'کسر نخست را در معکوس کسر دوم ضرب کن.',f'cancel(({a}/x)/({k}/x))')
 b.n(1,'تقسیم تک‌جمله‌ای و توان',d,f'در حاصل ({a}x^5)÷({a}x²)=x^n با x≠0، n چند است؟',3,'ضریب‌های برابر حذف و نماهای متغیر هم‌پایه تفریق می‌شوند.', '5-2')
 b.s(2,'تعریف‌نشدگی با مخرج تفاضل مربع‌ها',t,f'مقدارهای ممنوعِ (x+1)/(x²−{a*a}) را به صورت مجموعه بنویس.',[-a,a],'مخرج را به دو عامل مزدوج تجزیه کن؛ هر دو ریشه ممنوع‌اند.')
 b.m(2,'ساده‌سازی تفاضل مربع‌ها',t,f'برای x≠{a}، ساده‌شدهٔ (x²−{a*a})/(x−{a}) کدام است؟',f'x+{a}',[f'x−{a}',f'x²+{a}',str(a)],'صورت را به دو مزدوج تجزیه و عامل x−a را حذف کن.',expression=f'(x**2-{a*a})/(x-{a})',option_exprs=[f'x+{a}',f'x-{a}',f'x**2+{a}',str(a)])
 b.m(2,'ساده‌سازی مربع کامل',t,f'با فرض x≠{a}، (x²−{2*a}x+{a*a})/(x−{a}) کدام است؟',f'x−{a}',[f'x+{a}','1',f'x²−{a*a}'],'صورت مربع کاملِ همان عامل مخرج است؛ یک عامل باقی می‌ماند.',expression=f'(x**2-{2*a}*x+{a*a})/(x-{a})',option_exprs=[f'x-{a}',f'x+{a}','1',f'x**2-{a*a}'])
 b.n(2,'تغییر علامت در مخرج قرینه',o,f'برای x≠{a}، حاصل (x−{a})/({a}−x) چند است؟',-1,'دو عامل قرینه‌اند و نسبت آن‌ها منفی یک است.',f'cancel((x-{a})/({a}-x))')
 b.m(2,'عامل در برابر جملهٔ قابل حذف',t,'کدام ساده‌سازی برای x≠0 درست است؟','(x²+x)/x=x+1',['(x+1)/x=1+1','(x+2)/x=2','(x²+1)/x=x+1'],'حذف، روی عامل مشترکِ کل صورت و مخرج مجاز است؛ جمله‌ای از یک جمع را تنها حذف نکن.')
 b.n(2,'جمع با مخرج‌های متناسب',o,f'برای x≠0، حاصل 1/x+1/({k}x) را به صورت c/x می‌نویسیم؛ c چند است؟',F(k+1,k),'مخرج مشترک kx است؛ صورت کسر اول هم باید در k ضرب شود.',f'cancel((1/x+1/({k}*x))*x)')
 b.n(2,'ضرب با حذف عوامل جبری متقاطع',o,f'برای مقدارهای مجاز x، حاصل ((x−{a})/(x+{a}))×((x+{a})/(x−{a})) چند است؟',1,'عامل‌ها حذف می‌شوند، اما x=a و x=−a همچنان مجاز نیستند.',f'cancel(((x-{a})/(x+{a}))*((x+{a})/(x-{a})))')
 b.m(2,'تقسیم دو عبارت گویا',o,f'برای مقدارهای مجاز، حاصل [(x+{a})/(x−1)]÷[({k})/(x−1)] کدام است؟',f'(x+{a})/{k}',[f'{k}/(x+{a})',f'(x+{a})/(x−1)',str(k)],'کسر دوم را وارونه و سپس عامل مشترک را حذف کن.',expression=f'((x+{a})/(x-1))/({k}/(x-1))',option_exprs=[f'(x+{a})/{k}',f'{k}/(x+{a})',f'(x+{a})/(x-1)',str(k)])
 b.n(2,'تقسیم چندجمله‌ای بر تک‌جمله‌ای',d,f'در حاصل ({a}x³+{k}x²)/x با x≠0، ضریب x چند است؟',k,'هر جملهٔ صورت را جدا بر تک‌جمله‌ای مخرج تقسیم کن.',f'cancel(({a}*x**3+{k}*x**2)/x).coeff(x)')
 b.n(2,'خارج قسمت تقسیم درجهٔ دو',d,f'در تقسیم x²+{a+1}x+{a} بر x+1، جملهٔ ثابت خارج‌قسمت چند است؟',a,'با عامل‌گیری یا تقسیم طولانی، خارج‌قسمت را به دست آور و با ضرب کنترل کن.',f'div(x**2+{a+1}*x+{a},x+1,x)[0].coeff(x,0)')
 b.n(2,'باقی‌ماندهٔ تقسیم بر دو جمله‌ای',d,f'باقی‌ماندهٔ تقسیم x²+{a} بر x−1 چند است؟',a+1,'تقسیم را انجام بده یا از رابطهٔ درستی تقسیم در x=1 استفاده کن.',f'rem(x**2+{a},x-1,x)')
 b.m(2,'درجهٔ باقی‌مانده',d,'اگر مقسوم‌علیه درجهٔ دو باشد، کدام عبارت نمی‌تواند باقی‌ماندهٔ تقسیم استاندارد باشد؟','x²+1',['0','x+1','−3'],'باقی‌مانده باید صفر یا درجه‌ای کمتر از درجهٔ مقسوم‌علیه داشته باشد.')
 b.s(3,'دامنهٔ کسرِ ظاهراً ساده‌شده',t,f'مقدارهای ممنوعِ (x²−{a*a})/[(x−{a})(x+1)] را بنویس.',[a,-1],'حتی اگر x−a حذف شود، دامنه را از مخرج اصلی تعیین کن.')
 b.s(3,'دامنهٔ تقسیم عبارت گویا',o,f'در عبارت [1/(x−{a})]÷[(x+{k})/(x−1)]، همهٔ مقدارهای ممنوع x را بنویس.',[a,1,-k],'مخرج‌های اولیه نباید صفر شوند و خود مقسوم‌علیه هم نباید صفر باشد.')
 b.m(3,'جمع با دو مخرج خطی متفاوت',o,f'برای مقدارهای مجاز، حاصل 1/(x−{a})+1/(x+{a}) کدام است؟',f'2x/(x²−{a*a})',[f'2/(2x)',f'2x/(x²+{a*a})',f'{2*a}/(x²−{a*a})'],'مخرج مشترک حاصل ضرب دو عامل است و صورت‌ها پس از هم‌مخرج کردن جمع می‌شوند.',expression=f'1/(x-{a})+1/(x+{a})',option_exprs=[f'2*x/(x**2-{a*a})','2/(2*x)',f'2*x/(x**2+{a*a})',f'{2*a}/(x**2-{a*a})'])
 b.m(3,'تفریق مخرج‌های قرینه',o,f'حاصل 1/(x−{a})−1/({a}−x) برای x≠{a} کدام است؟',f'2/(x−{a})',['0',f'1/(x−{a})',f'−2/(x−{a})'],'مخرج دوم قرینهٔ اول است؛ منفیِ بیرونی و منفیِ مخرج با هم مثبت می‌شوند.',expression=f'1/(x-{a})-1/({a}-x)',option_exprs=[f'2/(x-{a})','0',f'1/(x-{a})',f'-2/(x-{a})'])
 b.m(3,'کسر مرکب با صورت جمع',o,'برای x≠0 و x≠−1، حاصل (1+1/x)/(1/x) کدام است؟','x+1',['1+1/x','x','1/(x+1)'],'صورت و مخرج کسر بزرگ را در x ضرب کن؛ صورت به x+1 و مخرج به یک تبدیل می‌شود.',expression='(1+1/x)/(1/x)',option_exprs=['x+1','1+1/x','x','1/(x+1)'])
 b.m(3,'ضرب پس از دو تجزیه',o,f'برای مقدارهای مجاز، حاصل [(x²−{a*a})/(x+1)]×[(x+1)/(x−{a})] کدام است؟',f'x+{a}',[f'x−{a}','1',f'x²−{a*a}'],'پیش از ضرب گسترده، صورت را تجزیه کن و عامل‌های مشترک را حذف کن.',expression=f'((x**2-{a*a})/(x+1))*((x+1)/(x-{a}))',option_exprs=[f'x+{a}',f'x-{a}','1',f'x**2-{a*a}'])
 b.n(3,'ضریب خارج‌قسمت تقسیم چندجمله‌ای',d,f'در تقسیم x³+{a}x²+{k}x+1 بر x+1، ضریب x در خارج‌قسمت چند است؟',a-1,'در تقسیم طولانی، بعد از هر ضرب تمام مقسوم‌علیه را کم کن و علامت‌ها را تغییر بده.',f'div(x**3+{a}*x**2+{k}*x+1,x+1,x)[0].coeff(x)')
 b.n(3,'رابطهٔ درستی تقسیم',d,f'اگر مقسوم‌علیه x−{a}، خارج‌قسمت x+{k} و باقی‌مانده 2 باشد، مقدار مقسوم در x={a} چند است؟',2,'در رابطهٔ مقسوم=مقسوم‌علیه×خارج‌قسمت+باقی‌مانده، عامل اول در x=a صفر می‌شود.',f'(({a}-{a})*({a}+{k})+2)')
 b.n(3,'بخش‌پذیری و پارامتر ثابت',d,f'برای اینکه x²+{a}x+c بر x−1 بخش‌پذیر باشد، c چند است؟',-a-1,'باقی‌مانده باید صفر باشد؛ مقدار مقسوم در x=1 را برابر صفر قرار بده.',f'-1-{a}')
 b.n(3,'مقسوم با جملهٔ مفقود',d,f'باقی‌ماندهٔ تقسیم x³+{a} بر x−2 چند است؟',8+a,'جمله‌های با ضریب صفر را در تقسیم فراموش نکن؛ رابطهٔ درستی تقسیم هم کنترل می‌دهد.',f'rem(x**3+{a},x-2,x)')
 b.s(3,'دامنهٔ مخرجِ مربع کامل',t,f'عبارت 1/(x²−{2*a}x+{a*a}) در چه مقدارهایی تعریف نشده است؟ به صورت مجموعه بنویس.',[a],'مخرج مربع کامل است و فقط یک ریشهٔ متمایز دارد.')
 b.n(4,'ساده‌سازی ترکیبی و مقدار عددی',o,f'برای x={a+2}، مقدار [1/(x−{a})+1/(x+{a})]×(x²−{a*a}) چند است؟',2*a+4,'ابتدا جمع کسرها را ساده کن؛ سپس عامل مخرج حذف و فقط دو برابر x باقی می‌ماند.',f'(1/({a+2}-{a})+1/({a+2}+{a}))*(({a+2})**2-{a*a})')
 b.m(4,'معکوس مجموع در کسر مرکب',o,f'برای مقدارهای مجاز، 1/[1/(x−{a})+1/(x+{a})] کدام است؟',f'(x²−{a*a})/(2x)',[f'2x/(x²−{a*a})','2x',f'1/(2x)'],'ابتدا مجموع داخل مخرج را یک کسر کن؛ سپس معکوس همان کسر را بگیر.',expression=f'1/(1/(x-{a})+1/(x+{a}))',option_exprs=[f'(x**2-{a*a})/(2*x)',f'2*x/(x**2-{a*a})','2*x','1/(2*x)'])
 b.s(4,'مقدار ممنوع پنهان در مخرج مرکب',o,f'همهٔ مقدارهای ممنوع 1/[1/(x−{a})+1/(x+{a})] را بنویس.',[-a,0,a],'علاوه بر دو مخرج داخلی، مجموعی که مخرج کسر بزرگ است نباید صفر شود.')
 b.n(4,'پارامترِ ضریب برای باقی‌ماندهٔ مشخص',d,f'اگر باقی‌ماندهٔ x²+cx+{a} بر x−2 برابر {a+10} باشد، c چند است؟',3,'در x=2 رابطهٔ درستی تقسیم می‌دهد چهار به‌علاوهٔ دو برابر c به‌علاوهٔ ثابت برابر باقی‌مانده است.',f'({a+10}-4-{a})/2')
 b.m(4,'تقسیم با مقسوم‌علیهٔ درجهٔ دو',d,f'باقی‌ماندهٔ تقسیم x³+{a}x²+{k} بر x²−1 کدام است؟',f'x+{a+k}',[f'x−{a+k}',str(a+k),f'−x+{a+k}'],'درجهٔ باقی‌مانده باید کمتر از دو باشد؛ تقسیم طولانی و رابطهٔ کنترل، هر دو ضریب را تعیین می‌کنند.',expression=f'rem(x**3+{a}*x**2+{k},x**2-1,x)',option_exprs=[f'x+{a+k}',f'x-{a+k}',str(a+k),f'-x+{a+k}'])
 b.n(4,'حفظ دامنه هنگام صفر شدن صورت',t,f'عبارت (x−{a})/(x−{a}) در x={a+1} منهای مقدار آن در x={a+2} چند است؟',0,'هر دو مقدار مجازند و کسر در هر دو برابر یک است؛ مقدار ممنوع هنوز x=a است.',f'(({a+1}-{a})/({a+1}-{a}))-(({a+2}-{a})/({a+2}-{a}))')
 b.m(4,'کسر یک‌واحد منهای عبارت گویا',o,f'برای x≠{a}، ساده‌شدهٔ 1−(x+{a})/(x−{a}) کدام است؟',f'−{2*a}/(x−{a})',[f'0',f'{2*a}/(x−{a})',f'−{a}/(x−{a})'],'عدد یک را با مخرج x−a بنویس؛ منفی باید به هر دو جملهٔ صورت دوم برسد.',expression=f'1-(x+{a})/(x-{a})',option_exprs=[f'-{2*a}/(x-{a})','0',f'{2*a}/(x-{a})',f'-{a}/(x-{a})'])
 b.n(4,'تعداد ریشه‌های مجاز پس از ساده‌سازی',t,f'برای حل (x²−{a*a})/(x−{a})=0 چند جواب حقیقی مجاز وجود دارد؟',1,'صفرهای صورت را پیدا کن ولی ریشهٔ ممنوع مخرج را کنار بگذار؛ فقط منفی a می‌ماند.', 'Integer(1)')
 b.essay(2,'توجیه حذف عامل و حفظ دامنه',t,'چرا (x²−9)/(x−3)=x+3 فقط برای x≠3 برقرار است؟','صورت به (x−3)(x+3) تجزیه می‌شود؛ حذف عامل تنها وقتی مجاز است که آن عامل صفر نباشد؛ عبارت اولیه در x=3 تعریف نشده است.',['تجزیهٔ درست.','شرط حذف عامل.','دامنهٔ اولیه.'])
 b.essay(3,'ساده‌سازی با نوشتن همه محدودیت‌ها',o,'عبارت [(x²−4)/(x−1)]÷[(x+2)/(x−1)] را ساده و همهٔ مقدارهای ممنوع را بنویس.','مقدارهای x=1 و x=−2 ممنوع‌اند؛ با ضرب در معکوس و حذف عامل‌ها، حاصل x−2 است.',['مخرج‌های اولیه.','ناصفر بودن مقسوم‌علیه.','تجزیه و جواب همراه دامنه.'])
 b.essay(3,'تقسیم طولانی و رابطهٔ کنترل',d,'x²−5x+8 را بر x−2 تقسیم و رابطهٔ درستی تقسیم را بنویس.','خارج‌قسمت x−3 و باقی‌مانده 2 است؛ x²−5x+8=(x−2)(x−3)+2.',['مرتب‌سازی و تقسیم دو مرحله‌ای.','خارج‌قسمت و باقی‌مانده.','کنترل با ضرب و جمع.'])
 b.essay(4,'تشخیص حذف نامجاز در صورت جمع',t,'یک دانش‌آموز (x+3)/x را برابر 3 می‌داند؛ خطایش را توضیح بده و با یک مقدار مجاز بررسی کن.','x عامل مشترکِ کل صورت نیست؛ کسر برابر 1+3/x است؛ مثلاً در x=3 مقدار دو است و با سه برابر نیست.',['فرق عامل و جمله.','شکل درست همراه x≠0.','مثال نقض معتبر.'])
 return b.finish()
